import{_ as e,o as d,c as a,ag as s}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 6 — Databases","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_06_Databases.md","filePath":"todo/study_plan/parts/Part_06_Databases.md"}'),n={name:"todo/study_plan/parts/Part_06_Databases.md"};function o(r,t,i,l,c,h){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="part-6-—-databases" tabindex="-1">Part 6 — Databases <a class="header-anchor" href="#part-6-—-databases" aria-label="Permalink to &quot;Part 6 — Databases&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 4 (shared with start of Part 7). <strong>Budget: ~7-8 hrs.</strong></p></blockquote><h2 id="_6-databases-—-topic-inventory" tabindex="-1">6 Databases — topic inventory <a class="header-anchor" href="#_6-databases-—-topic-inventory" aria-label="Permalink to &quot;6 Databases — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Normalization (1NF–3NF, BCNF) — and when to denormalize</td><td>🔴 💼 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: normalize-vs-denormalize philosophy (SQL vs NoSQL) covered; 1NF–3NF/BCNF forms pending</td><td>📖 <code>databases/sql_vs_nosql/SqlVsNosql.md</code> (philosophy only)</td></tr><tr><td>2</td><td>Primary keys, foreign keys, surrogate vs natural</td><td>🔴 💼 🎯</td><td>M</td><td>1 hr 5 min</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: FK / referential integrity / orphaned records / app-vs-DB enforcement covered; surrogate vs natural keys pending</td><td>📖 <code>databases/sql_vs_nosql/SqlVsNosql.md</code> (FK part) · 💻 Warm-up: basic CRUD on a users table from memory — CREATE TABLE / INSERT / SELECT WHERE / UPDATE / DELETE (20 min)</td></tr><tr><td>3</td><td>Indexes — B-tree, composite, covering, partial; INCLUDE columns</td><td>🔴 💼 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 Use The Index, Luke! — Markus Winand (free, dip-in reference)</td></tr><tr><td>4</td><td>Query planner / EXPLAIN — reading plans, identifying full scans</td><td>🔴 💼 🎯</td><td>D</td><td>3 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 Vlad Mihalcea blog on EXPLAIN ANALYZE · 💻 Warm-up: GROUP BY + COUNT/SUM/AVG/HAVING/ORDER BY from scratch (20 min)</td></tr><tr><td>5</td><td>Joins — nested loop, hash, merge; when each is chosen</td><td>🔴 💼 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write LEFT / INNER / RIGHT JOIN on orders + customers, observe result-set differences (30 min)</td></tr><tr><td>6</td><td>ACID — what each letter actually guarantees</td><td>🔴 💼 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: atomicity/rollback + transactions-not-SQL-only covered; letter-by-letter guarantees pending</td><td>📖 <code>databases/sql_vs_nosql/SqlVsNosql.md</code> (transactions part)</td></tr><tr><td>7</td><td>Isolation levels — read uncommitted, read committed, repeatable read, serializable</td><td>🔴 💼 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 <em>Designing Data-Intensive Applications</em> ch 7 (Kleppmann — single chapter, ~45 min)</td></tr><tr><td>8</td><td>Anomalies — dirty read, non-repeatable, phantom, write skew, lost update</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Read replicas — async lag, read-after-write</td><td>🔴 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Sharding — strategies (range, hash, directory), resharding pain</td><td>🔴 💼 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: what sharding is + when/when-not to shard (shard-last answer) covered; strategies + resharding pain pending</td><td>📖 <code>databases/sql_vs_nosql/SqlVsNosql.md</code> (when-to-shard only)</td></tr><tr><td>11</td><td>Key-value (Redis, DynamoDB, Memcached)</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Document (MongoDB, DynamoDB)</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: MongoDB schema flexibility / validation / transactions / document-modeling limits covered; DynamoDB pending</td><td>📖 <code>databases/sql_vs_nosql/SqlVsNosql.md</code> (MongoDB parts)</td></tr><tr><td>13</td><td>MySQL — InnoDB internals, gap locks, replication</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>PostgreSQL — MVCC, vacuum, indexes, extensions</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>Redis — data types, persistence, eviction, clustering, pub/sub, streams</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 redis.io &quot;Introduction to Redis&quot; (~30 min)</td></tr><tr><td>16</td><td>MVCC — Postgres vs MySQL implementations</td><td>🟠 💼</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>Locks — row, gap, next-key (MySQL specifically)</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>Deadlocks — detection, prevention</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Transactions — savepoints, distributed, XA, 2PC</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Window functions (ROW_NUMBER, RANK, LAG, LEAD)</td><td>🟠 💼</td><td>MP</td><td>1 hr 50 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: ROW_NUMBER / RANK / LAG over PARTITION BY — find top-N per category, find diff between consecutive rows (20 min)</td></tr><tr><td>21</td><td>CTEs (WITH), recursive CTEs</td><td>🟠 💼</td><td>MP</td><td>1 hr 55 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: WITH non-recursive + recursive CTE for org-chart hierarchy traversal (25 min)</td></tr><tr><td>22</td><td>Materialized views</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>23</td><td>Stored procedures / triggers — and why most teams avoid them now</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>24</td><td>Schema migrations safely (Flyway, Liquibase) — backward-compatible changes</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>25</td><td>Connection pooling — HikariCP, sizing math</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 HikariCP &quot;About Pool Sizing&quot; wiki (~15 min, gold)</td></tr><tr><td>26</td><td>Caching layer in front (Redis)</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>27</td><td>Vertical vs horizontal scaling</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>28</td><td>Multi-master, conflict resolution</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>29</td><td>Wide-column (Cassandra, ScyllaDB, HBase)</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>30</td><td>Graph (Neo4j, Neptune)</td><td>🟠 💼 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: fraud-detection use cases (shared devices, cycles) covered; Neo4j/Neptune specifics pending</td><td>📖 <code>databases/graph_and_graphql/GraphDbAndGraphQl.md</code> (use cases only)</td></tr><tr><td>31</td><td>Time-series (Prometheus, InfluxDB, TimescaleDB)</td><td>🟠 💼 🎯</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>32</td><td>Search (Elasticsearch, OpenSearch)</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>33</td><td>DynamoDB — partition keys, GSI/LSI, hot partitions, on-demand vs provisioned</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>34</td><td>Elasticsearch — inverted index, mapping, analyzers</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>35</td><td>Partitioning (range, list, hash)</td><td>🟡</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>36</td><td>JSON columns</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>37</td><td>Vector (pgvector, Pinecone, Weaviate, Milvus) — also covered in GenAI</td><td>🟡 🆕</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>38</td><td>Cassandra — partition + clustering keys, tunable consistency</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>39</td><td>MongoDB — sharding, secondary indexes, aggregation pipeline</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>40</td><td>SQL vs NoSQL — when each fits: schemaless myth, transactions myth, relational-modeling argument, who-enforces-relationships, DB-level security (defense in depth)</td><td>🔴 💼 🎯</td><td>M</td><td>1 hr</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>~1 hr (ChatGPT)</td><td>📖 <code>databases/sql_vs_nosql/SqlVsNosql.md</code></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~37.92 hrs</td><td>~3.45 wk</td><td>~1 hr so far (row 40 done; rows 1, 2, 6, 10, 12 partial)</td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~64.92 hrs</td><td>~5.9 wk</td><td>~1 hr so far (row 30 also partial)</td></tr><tr><td>Full Part (all items including 🟡)</td><td>~70.17 hrs</td><td>~6.4 wk</td><td>~1 hr so far</td></tr></tbody></table><blockquote><p>Database is foundational for most senior interviews. Isolation levels + indexes + EXPLAIN are interview-canonical and worth Mastery time.</p></blockquote><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>B-tree index structure:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Root[&quot;Root node&lt;br/&gt;keys: [50 | 100]&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I1[&quot;Internal&lt;br/&gt;keys: [20 | 35]&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I2[&quot;Internal&lt;br/&gt;keys: [70 | 85]&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I3[&quot;Internal&lt;br/&gt;keys: [120 | 150]&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L1[&quot;Leaf: (10→row), (15→row), (20→row)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L2[&quot;Leaf: (35→row), (40→row), (50→row)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L3[&quot;Leaf: (70→row), (85→row), (100→row)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L4[&quot;Leaf: (120→row), (150→row), (200→row)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Root --&gt; I1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Root --&gt; I2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Root --&gt; I3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I1 --&gt; L1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I1 --&gt; L2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I2 --&gt; L3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    I3 --&gt; L4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L1 -.-&gt;|next| L2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L2 -.-&gt;|next| L3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L3 -.-&gt;|next| L4</span></span></code></pre></div><blockquote><p>Traversal from root to leaf is O(log n) on the branching factor. Leaves are linked horizontally so range scans (<code>WHERE x BETWEEN a AND b</code>, <code>ORDER BY x</code>) walk leaves sequentially without re-descending the tree.</p></blockquote><p><strong>MVCC version chain:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Row[&quot;Row &#39;X&#39; — version chain&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        V1[&quot;v1&lt;br/&gt;txid 100&lt;br/&gt;value = A&quot;] --&gt; V2[&quot;v2&lt;br/&gt;txid 105&lt;br/&gt;value = B&quot;] --&gt; V3[&quot;v3&lt;br/&gt;txid 110&lt;br/&gt;value = C&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T1[&quot;Tx@103&lt;br/&gt;(snapshot at 103)&quot;] -.-&gt;|sees| V1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T2[&quot;Tx@108&lt;br/&gt;(snapshot at 108)&quot;] -.-&gt;|sees| V2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T3[&quot;Tx@112&lt;br/&gt;(snapshot at 112)&quot;] -.-&gt;|sees| V3</span></span></code></pre></div><blockquote><p>Readers don&#39;t block writers; each tx sees the snapshot consistent with its start time. Old versions get reclaimed by VACUUM (Postgres) or undo log truncation (InnoDB).</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through the 4 isolation levels and which anomalies each prevents. <ul><li><strong>Why asked:</strong> Senior-canonical. Read Uncommitted → no protection (dirty reads possible). Read Committed → no dirty reads. Repeatable Read → no non-repeatable reads (but phantom reads still possible in standard SQL; in MySQL InnoDB, gap locks prevent phantoms here too). Serializable → no anomalies. Plus the anomaly nobody mentions: write skew (only Serializable prevents it cleanly; Snapshot Isolation doesn&#39;t).</li></ul></li><li><strong>Q:</strong> EXPLAIN ANALYZE on a query shows a sequential scan on a 50M-row table. Walk through your diagnosis. <ul><li><strong>Why asked:</strong> Production-canonical bug. Check: index existence on WHERE columns, index selectivity (rows planner expects vs actual — if estimates are off, ANALYZE the table), index disqualification (functions on indexed columns, type mismatches, leading wildcard LIKE), index on wrong column order for composite indexes, planner stats stale.</li></ul></li><li><strong>Q:</strong> When does the query planner pick nested loop vs hash join vs merge join? <ul><li><strong>Why asked:</strong> Tests join algorithm understanding. Nested loop: small outer × indexed inner, or no good alternative. Hash join: medium-large unsorted tables, equality predicate, build hash on smaller side. Merge join: both inputs already sorted on the join key (often by index), large datasets.</li></ul></li><li><strong>Q:</strong> How would you handle read-after-write with async read replicas? <ul><li><strong>Why asked:</strong> Practical senior consistency problem. Options: (1) route reads for the just-updated entity to primary for X seconds (sticky session, common). (2) timestamp-versioning — client tracks write timestamp, replica refuses to serve reads older than that. (3) accept stale reads where business allows. (4) synchronous replication (perf cost). KYC platforms often pick option 1 with a short window.</li></ul></li><li><strong>Q:</strong> Compare sharding strategies: range vs hash vs directory. Which one does DynamoDB use? <ul><li><strong>Why asked:</strong> Senior scaling design. Range = sorted by key, easy range queries, but creates hot partitions on monotonic IDs. Hash = even distribution, no range queries, partition by hash(key). Directory = lookup table maps keys to shards, max flexibility, extra hop. DynamoDB = hash on partition key + optional sort key (range within partition).</li></ul></li><li><strong>Q:</strong> MVCC in Postgres vs MySQL InnoDB — what&#39;s the practical difference? <ul><li><strong>Why asked:</strong> Differentiates engineers who&#39;ve read DDIA from those who haven&#39;t. Postgres: stores row versions in heap, vacuum reclaims dead tuples (vacuum lag = bloat). MySQL InnoDB: stores undo logs separately, &quot;undo tablespace&quot; can grow. Both implement read snapshots without read locks; vacuum vs undo log differ operationally.</li></ul></li><li><strong>Q:</strong> HikariCP sizing — your service has 8 cores. What pool size for IO-bound DB calls? <ul><li><strong>Why asked:</strong> Operational fluency. NOT 8 (that&#39;s CPU-bound rule). Pool sizing for IO-bound: Little&#39;s Law, depends on wait/compute ratio. Typical sweet spot: 10-30 for modest workloads. Counter-intuitive insight: increasing pool size past a point makes things SLOWER (DB contention). HikariCP wiki has the formula.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> You have a composite index on <code>(a, b, c)</code>. Will a query with WHERE <code>b = 5 AND c = 10</code> use the index? <ul><li><strong>Gotcha:</strong> No — leftmost prefix rule. The index can be used by WHERE on (a), (a,b), or (a,b,c). Skipping <code>a</code> disqualifies the index. Fix: separate index on (b, c), or reorder the composite to (b, c, a) if other queries don&#39;t need leading a.</li></ul></li><li><strong>Q:</strong> Repeatable Read in MySQL InnoDB prevents phantom reads. SQL standard says it doesn&#39;t. Why? <ul><li><strong>Gotcha:</strong> Standard says Repeatable Read prevents non-repeatable reads but NOT phantom reads. MySQL InnoDB adds <em>gap locks</em> + <em>next-key locks</em> on top, locking the gaps between rows in range queries, which incidentally prevents phantoms. So InnoDB&#39;s &quot;Repeatable Read&quot; is actually stronger than the standard. Postgres takes a different route — Repeatable Read implements Snapshot Isolation.</li></ul></li><li><strong>Q:</strong> You wrap two <code>INSERT</code> statements in <code>BEGIN; INSERT; INSERT; COMMIT;</code>. The first succeeds, the second deadlocks and rolls back. What&#39;s the state of the first? <ul><li><strong>Gotcha:</strong> Also rolled back. The COMMIT was never reached. A deadlock on any statement in a transaction throws an exception that, if uncaught, leaves the transaction in a rolled-back-only state — the framework typically rolls back. Common bug: catching the exception and continuing thinking the first INSERT survives.</li></ul></li><li><strong>Q:</strong> UUID as primary key on a high-insert table. What&#39;s the performance trap? <ul><li><strong>Gotcha:</strong> Random UUIDs cause B-tree index page splits all over the tree (since inserts hit random leaf pages). Sequential keys append to the end of the index — much faster. Mitigations: UUIDv7 (time-ordered), <code>gen_random_uuid()</code> with a separate sequential ID for clustering, or accept the cost for the security/distribution benefits.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Isolation levels + anomalies matrix</strong> (~3.5 hrs combined) — interview-canonical. Build a 4×5 matrix (4 isolation levels × 5 anomalies) showing which level prevents which. Walk through write skew specifically — the anomaly nobody mentions.</li><li><strong>Indexes deep + EXPLAIN ANALYZE walkthroughs</strong> (~5 hrs combined) — read 3-5 real query plans, diagnose each. Composite index ordering, covering indexes, partial indexes, INCLUDE columns. Use real KYC queries if available.</li><li><strong>Sharding strategies walkthrough</strong> (~3 hrs) — range/hash/directory, hot partition mitigation, resharding pain (cellular architecture, gradual migration). Connect to DynamoDB partition key design.</li><li><strong>PostgreSQL or MySQL deep dive</strong> (~3 hrs) — pick the one your platform actually uses. MVCC, vacuum (Postgres) or undo log (MySQL), index types specific to that engine, common production gotchas.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up SQL exercises are listed inline in the topic-table Resources column (counted in main Time summary). The longer exercises below are tracked separately. Use a local Postgres or MySQL via Docker.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Index impact via EXPLAIN ANALYZE</strong> (~45 min) — create a <code>users</code> table with 1M rows. Run <code>WHERE email = ?</code> query — observe sequential scan + cost. Add index on email. Re-run — observe index scan. Then run <code>WHERE LOWER(email) = ?</code> — observe sequential scan returned (function disqualifies index). Fix with functional index.</li><li><strong>Composite index leftmost-prefix rule</strong> (~30 min) — create index <code>(country, city, name)</code>. Run three queries: <code>WHERE country=?</code>, <code>WHERE country=? AND city=?</code>, <code>WHERE city=?</code>. EXPLAIN each — see which use the index and why the third doesn&#39;t (no leading <code>country</code>).</li><li><strong>Reproduce + diagnose a deadlock</strong> (~30 min) — two transactions, two rows, update in opposite order. Watch one error with &quot;deadlock detected.&quot; Inspect <code>pg_stat_activity</code> and Postgres logs to find the cycle.</li><li><strong>N+1 query observation + fix</strong> (~30 min) — Hibernate/JPA query loading <code>Order</code> entities with lazy <code>OrderItems</code>. Enable SQL logging (<code>logging.level.org.hibernate.SQL=DEBUG</code>). Iterate orders accessing items. Observe N+1 SELECT statements. Fix with <code>JOIN FETCH</code> or <code>@EntityGraph</code>. Compare query counts.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="5"><li><strong>Reproduce isolation anomalies</strong> (~60 min) — two <code>psql</code> sessions side by side, both starting a transaction. Set isolation level to <code>READ COMMITTED</code>. Demonstrate: dirty read prevented, but non-repeatable read happens. Switch to <code>REPEATABLE READ</code>. Demonstrate non-repeatable prevented. Try a phantom (range query) and observe Postgres behavior.</li><li><strong>HikariCP pool sizing experiment</strong> (~45 min) — write a load test hitting an endpoint that does a DB call. Vary pool size: 1, 10, 50, 200. Plot throughput. Observe sweet spot (typically 10–30) and the <em>decrease</em> at higher pool sizes due to DB contention.</li><li><strong>MVCC vacuum observation</strong> (Postgres-specific, ~45 min) — run a tight <code>UPDATE</code> loop on a small table (say 1000 rows). Watch table size grow in <code>pg_total_relation_size</code> despite row count constant. Manual <code>VACUUM ANALYZE</code> to reclaim. Observe size drop.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.25 hrs</td><td>~0.2 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~4.75 hrs</strong></td><td><strong>~0.45 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~1 hr 55 min for Part 6 across 5 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. ACID — one-line each.</strong> A. Atomicity: all-or-nothing transaction. Consistency: DB constraints/invariants hold at transaction boundaries. Isolation: concurrent transactions don&#39;t see each other&#39;s partial state (level-dependent). Durability: committed data survives crashes.</p><p><strong>Q. Read Committed vs Repeatable Read — what does the second add?</strong> A. Read Committed prevents dirty reads (you only see committed data) but lets the same row read twice return different values if another transaction modified it between reads. Repeatable Read keeps each row&#39;s value stable for the duration of your transaction (snapshot).</p><p><strong>Q. B-tree vs hash index — quick rule.</strong> A. B-tree: range queries, ORDER BY, equality. Hash: only equality, faster for it, no ordering. Postgres has both; most workloads use B-tree by default.</p><p><strong>Q. MVCC in one sentence.</strong> A. Multi-version concurrency control — readers see a snapshot (no read locks), writers create new row versions; old versions cleaned up by vacuum (Postgres) or via undo log (InnoDB). Trade-off: storage bloat for read concurrency.</p><p><strong>Q. Read replica lag — three mitigation strategies.</strong> A. (1) Read primary after a write within a short window (sticky session). (2) Pass write timestamp on each query, refuse stale reads. (3) Use synchronous replication for critical reads (perf cost).</p><p><strong>Q. Sharding strategies — when each fits.</strong> A. Range: data has natural order, range queries common, watch hot partitions. Hash: even distribution, no range queries possible without scatter. Directory: max flexibility, extra lookup hop, central directory becomes bottleneck.</p><p><strong>Q. HikariCP sizing rule of thumb for IO-bound work.</strong> A. NOT cores. Use Little&#39;s Law: pool ≈ cores × (1 + wait/compute). Typical web service with DB calls: 10-30. Past a point, increasing pool size HURTS — DB contention dominates.</p>`,37)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
